def coerce_datetime(v):
    """Best-effort conversion of worksheet date-like values to a datetime, preserving Excel-like serial dates."""
    if v is None:
        return None
    if isinstance(v, datetime.datetime):
        return v.replace(tzinfo=None)
    if isinstance(v, datetime.date):
        return datetime.datetime(v.year, v.month, v.day)
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        try:
            return from_excel(v)
        except Exception:
            return None
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        # Try a few common spreadsheet date formats, then dateutil if available.
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%d/%m/%Y", "%Y/%m/%d", "%b %d %Y", "%B %d %Y"):
            try:
                return datetime.datetime.strptime(s, fmt)
            except Exception:
                pass
        try:
            from dateutil import parser
            return parser.parse(s).replace(tzinfo=None)
        except Exception:
            return None
    return None

def excel_date(year, month, day):
    """
    Reproduce Excel DATE normalization for positive day/month values well enough for
    DATE(YEAR(header),MONTH(header),31): day overflow rolls into following month.
    """
    # Normalize month first, as Excel does.
    y = int(year) + (int(month) - 1) // 12
    m = (int(month) - 1) % 12 + 1
    return datetime.datetime(y, m, 1) + datetime.timedelta(days=int(day) - 1)

def comparable_criterion(v):
    """Normalize simple SUMIFS equality criteria from cells; text matching in Excel is case-insensitive."""
    if v is None:
        return ""
    if isinstance(v, str):
        return v.strip().lower()
    # Dates/numbers are uncommon in the category column, but keep them comparable.
    if isinstance(v, datetime.datetime):
        return v
    if isinstance(v, datetime.date):
        return datetime.datetime(v.year, v.month, v.day)
    return v

def values_match_excel_simple(cell_value, criterion_value):
    """
    Simple exact-match SUMIFS criterion as used by a list of category names.
    Text comparisons are case-insensitive.  Blank criterion matches blank cells.
    """
    crit = comparable_criterion(criterion_value)
    val = comparable_criterion(cell_value)
    if crit == "":
        return val == ""
    if isinstance(crit, str) or isinstance(val, str):
        return str(val).strip().lower() == str(crit).strip().lower()
    return val == crit

