    """SUMIFS sums numeric values and treats blanks/non-numeric text as zero."""
    if v is None or isinstance(v, bool):
        return 0
    if isinstance(v, (int, float)):
        if isinstance(v, float) and math.isnan(v):
            return 0
        return v
    # Be permissive with numeric-looking text in case hidden inputs store numbers as strings.
    if isinstance(v, str):
        s = v.strip().replace(",", "")
        if not s:
            return 0
        try:
            return float(s)
        except Exception:
            return 0
    return 0

# Data columns from the quoted formula/layout:
# B = date criteria range, C = category criteria range, D = sum range.
date_col = 2
category_col = 3
sum_col = 4
data_start_row = min_row  # row 6

# Read all data rows, deriving the lower extent from actual used cells in B:D rather than the preview/formula's row 13.
last_data_row = data_start_row - 1
for r in range(data_start_row, ws.max_row + 1):
    if any(ws.cell(r, c).value is not None for c in (date_col, category_col, sum_col)):
        last_data_row = r

data_rows = []
for r in range(data_start_row, last_data_row + 1):
    dt = coerce_datetime(ws.cell(r, date_col).value)
    cat = ws.cell(r, category_col).value
    amt = ws.cell(r, sum_col).value
    data_rows.append((dt, cat, amt))

# Criteria list/range from the quoted formula: F10:F14.
# Keep duplicates and blanks, because SUM(SUMIFS(..., criteria_range, F10:F14)) would evaluate each cell in the list.
criteria_values = [ws.cell(r, 6).value for r in range(10, 15)]

# Compute the corrected array-SUMIFS result for each month header above the answer cells.
# This intentionally preserves the quoted date semantics:
# >= DATE(YEAR(header),MONTH(header),1) and <= DATE(YEAR(header),MONTH(header),31)
# (Excel DATE with day 31 can roll into the next month).
for c in range(min_col, max_col + 1):
    header_dt = coerce_datetime(ws.cell(min_row - 1, c).value)
    if header_dt is None:
        # If a header is not a date, SUMIFS would not produce a meaningful month result; leave unchanged.
        continue
    start_dt = excel_date(header_dt.year, header_dt.month, 1)
    end_dt = excel_date(header_dt.year, header_dt.month, 31)
    total = 0
    for crit in criteria_values:
        for dt, cat, amt in data_rows:
            if dt is None:
                continue
            if start_dt <= dt <= end_dt and values_match_excel_simple(cat, crit):
                total += numeric_for_sum(amt)
    # Write numeric literal, not a live formula.
    if isinstance(total, float) and total.is_integer():
